using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// .NET CIL/MSIL 翻译器
    /// 将 VML 汇编翻译为 .NET 中间语言（ILAsm 语法）
    ///
    /// VML 寄存器映射策略：
    ///   R0-R15 → .NET 局部变量（localloc + ldloc/stloc）
    ///   R12(BP) → 不映射（.NET 有自己的栈帧，由 CLR 管理）
    ///   R13(SP) → 不映射（.NET 操作数栈由 CLR 管理）
    ///   R15(RA) → 不映射（.NET 返回地址由 CLR 管理）
    ///
    /// 浮点寄存器 F0-F15 → 局部变量 20-35
    ///
    /// VML 内存操作 → 静态 int[] Memory 数组
    /// VML 栈操作 → .NET 计算栈（evaluation stack）
    /// </summary>
    public class TranslatorDotNET : TranslatorVM
    {
        public override string ARCH_NAME => "DotNET";

        // .NET 无硬件中断支持 — 所有中断指令为 NOP
        protected override string[] ContextRegNames() => new string[0];
        protected override string NativeInt(int vector) => "";
        protected override string NativeIret() => "";
        protected override string NativeCli() => "";
        protected override string NativeSti() => "";
        protected override void EmitNativeInt(int vector) => Emit("    // INT - .NET 无硬件中断");
        protected override void EmitNativeCli() => Emit("    // CLI - .NET 无中断控制");
        protected override void EmitNativeSti() => Emit("    // STI - .NET 无中断控制");

        // VML 寄存器 → .NET 局部变量索引映射
        private readonly Dictionary<int, int> REGISTER_MAP = new Dictionary<int, int>
        {
            { 0, 0 },   // R0 → local 0
            { 1, 1 },   // R1 → local 1
            { 2, 2 },   // R2 → local 2
            { 3, 3 },   // R3 → local 3
            { 4, 4 },   // R4 → local 4
            { 5, 5 },   // R5 → local 5
            { 6, 6 },   // R6 → local 6
            { 7, 7 },   // R7 → local 7
            { 8, 8 },   // R8 → local 8
            { 9, 9 },   // R9 → local 9
            { 10, 10 }, // R10 → local 10
            { 11, 11 }, // R11 → local 11
            // R12(BP), R13(SP), R15(RA) 由 CLR 管理，不映射
            { 14, 14 }, // R14 → local 14
        };

        // 浮点寄存器映射（映射到独立浮点局部变量）
        private readonly Dictionary<int, int> FLOAT_REGISTER_MAP = new Dictionary<int, int>
        {
            { 0, 20 }, { 1, 21 }, { 2, 22 }, { 3, 23 },
            { 4, 24 }, { 5, 25 }, { 6, 26 }, { 7, 27 },
            { 8, 28 }, { 9, 29 }, { 10, 30 }, { 11, 31 },
            { 12, 32 }, { 13, 33 }, { 14, 34 }, { 15, 35 }
        };

        // 比较结果临时变量
        private const int CMP_RESULT_SLOT = 15;
        private const int SP_SLOT = 16;
        private const int ALLOC_PTR_SLOT = 17;

        private int labelCounter = 0;

        public TranslatorDotNET(VmlProgram vmlProgram) : base(vmlProgram)
        {
        }

        protected override void EmitHeader()
        {
            Emit("// .NET CIL (ILAsm syntax) - Translated from VML");
            Emit("// Generated by VML Translator");
            Emit("");
            Emit(".assembly extern mscorlib {}");
            Emit(".assembly VMLProgram {}");
            Emit(".module VMLProgram.exe");
            Emit("");
            Emit("// === VML 内存模型 ===");
            Emit(".field public static int32[] Memory");
            Emit(".field public static int32 MemorySize");
            Emit(".field public static int32 AllocPtr");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("// === 数据段 ===");
                int addrCounter = 256;

                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is int intValue)
                    {
                        Emit($".field public static int32 data_{name} at {addrCounter}");
                        LabelMap[name] = addrCounter.ToString();
                        addrCounter += 4;
                    }
                    else if (value is string strValue)
                    {
                        // 字符串存储为字节数组在memory中
                        LabelMap[name] = addrCounter.ToString();
                        addrCounter += System.Text.Encoding.UTF8.GetByteCount(strValue) + 1;
                    }
                }
                Emit("");
            }
        }

        protected override void EmitCode()
        {
            Emit("// === 主程序入口 ===");
            Emit(".method public static void Main(string[] args) cil managed");
            Emit("{");
            Emit("    .entrypoint");
            Emit("    .maxstack 8");
            Emit($"    .locals init (");
            Emit("        [0] int32 R0,");
            Emit("        [1] int32 R1,");
            Emit("        [2] int32 R2,");
            Emit("        [3] int32 R3,");
            Emit("        [4] int32 R4,");
            Emit("        [5] int32 R5,");
            Emit("        [6] int32 R6,");
            Emit("        [7] int32 R7,");
            Emit("        [8] int32 R8,");
            Emit("        [9] int32 R9,");
            Emit("        [10] int32 R10,");
            Emit("        [11] int32 R11,");
            Emit("        [12] int32 R12,");  // BP (unused by CLR)
            Emit("        [13] int32 R13,");  // SP (unused by CLR)
            Emit("        [14] int32 R14,");
            Emit($"        [{CMP_RESULT_SLOT}] int32 CmpResult,");
            Emit($"        [{SP_SLOT}] int32 SP,");
            Emit($"        [{ALLOC_PTR_SLOT}] int32 AllocPtr,");
            Emit("        [18] int32 tmp0,");  // 临时变量
            Emit("        [19] int32 tmp1,");
            Emit("        [20] float32 F0,");
            Emit("        [21] float32 F1,");
            Emit("        [22] float32 F2,");
            Emit("        [23] float32 F3,");
            Emit("        [24] float32 F4,");
            Emit("        [25] float32 F5,");
            Emit("        [26] float32 F6,");
            Emit("        [27] float32 F7,");
            Emit("        [28] float32 F8,");
            Emit("        [29] float32 F9,");
            Emit("        [30] float32 F10,");
            Emit("        [31] float32 F11,");
            Emit("        [32] float32 F12,");
            Emit("        [33] float32 F13,");
            Emit("        [34] float32 F14,");
            Emit("        [35] float32 F15");
            Emit("    )");
            Emit("");

            // 初始化内存
            Emit("    // 初始化 VML 内存");
            Emit("    ldc.i4 1048576");  // 1MB
            Emit("    newarr [mscorlib]System.Int32");
            Emit("    stsfld int32[] VMLProgram::Memory");
            Emit("    ldc.i4 1048576");
            Emit("    stsfld int32 VMLProgram::MemorySize");
            Emit("");

            // 初始化SP
            Emit("    // 初始化栈指针");
            Emit("    ldc.i4 1048572");  // memorySize - 4
            Emit("    stloc SP");
            Emit("    ldloc SP");
            Emit("    stloc.s R13");
            Emit("");

            // 初始化数据段
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("    // 初始化数据段");
                int addrCounter = 256;
                foreach (var kvp in VmlProgram.DataSection)
                {
                    if (kvp.Value is int intValue)
                    {
                        Emit("    ldsfld int32[] VMLProgram::Memory");
                        Emit($"    ldc.i4 {addrCounter}");
                        Emit($"    ldc.i4 {intValue}");
                        Emit("    stelem.i4");
                        addrCounter += 4;
                    }
                    else if (kvp.Value is string strValue)
                    {
                        byte[] bytes = System.Text.Encoding.UTF8.GetBytes(strValue);
                        for (int i = 0; i < bytes.Length; i++)
                        {
                            Emit("    ldsfld int32[] VMLProgram::Memory");
                            Emit($"    ldc.i4 {addrCounter + i}");
                            Emit($"    ldc.i4 {(int)bytes[i]}");
                            Emit("    stelem.i4");
                        }
                        Emit("    ldsfld int32[] VMLProgram::Memory");
                        Emit($"    ldc.i4 {addrCounter + bytes.Length}");
                        Emit("    ldc.i4.0");
                        Emit("    stelem.i4");
                        addrCounter += bytes.Length + 1;
                    }
                }
                Emit("");
            }

            // 翻译每条指令
            foreach (var instr in VmlProgram.Instructions)
            {
                NormalizeAndTranslate(instr);
            }

            Emit("");
            Emit("    ret");
            Emit("}");
        }

        protected override void EmitFooter()
        {
            // 辅助方法
            Emit("");
            Emit("// === 辅助方法 ===");

            // MemRead
            Emit(".method public static int32 MemRead(int32 addr) cil managed");
            Emit("{");
            Emit("    .maxstack 8");
            Emit("    ldsfld int32[] VMLProgram::Memory");
            Emit("    ldarg.0");
            Emit("    ldelem.i4");
            Emit("    ret");
            Emit("}");
            Emit("");

            // MemWrite
            Emit(".method public static void MemWrite(int32 addr, int32 value) cil managed");
            Emit("{");
            Emit("    .maxstack 8");
            Emit("    ldsfld int32[] VMLProgram::Memory");
            Emit("    ldarg.0");
            Emit("    ldarg.1");
            Emit("    stelem.i4");
            Emit("    ret");
            Emit("}");
            Emit("");

            // VmlPrint
            Emit(".method public static void VmlPrint(int32 value) cil managed");
            Emit("{");
            Emit("    .maxstack 8");
            Emit("    ldstr \"{0}\");  ");
            Emit("    ldarg.0");
            Emit("    box [mscorlib]System.Int32");
            Emit("    call void [mscorlib]System.Console::Write(string, object)");
            Emit("    ret");
            Emit("}");
            Emit("");

            // VmlPrintLine
            Emit(".method public static void VmlPrintLine(int32 value) cil managed");
            Emit("{");
            Emit("    .maxstack 8");
            Emit("    ldarg.0");
            Emit("    call void [mscorlib]System.Console::WriteLine(int32)");
            Emit("    ret");
            Emit("}");
            Emit("");

            // VmlPrintString
            Emit(".method public static void VmlPrintString(int32 addr) cil managed");
            Emit("{");
            Emit("    .maxstack 8");
            Emit("    .locals init ([0] class [mscorlib]System.Text.StringBuilder sb, [1] int32 i, [2] int32 ch)");
            Emit("    newobj instance void [mscorlib]System.Text.StringBuilder::.ctor()");
            Emit("    stloc.0");
            Emit("    ldarg.0");
            Emit("    stloc.1");
            Emit("  loop_start:");
            Emit("    ldsfld int32[] VMLProgram::Memory");
            Emit("    ldloc.1");
            Emit("    ldelem.i4");
            Emit("    dup");
            Emit("    stloc.2");
            Emit("    brfalse loop_end");
            Emit("    ldloc.0");
            Emit("    ldloc.2");
            Emit("    conv.u2");
            Emit("    call instance class [mscorlib]System.Text.StringBuilder [mscorlib]System.Text.StringBuilder::Append(char)");
            Emit("    pop");
            Emit("    ldloc.1");
            Emit("    ldc.i4.1");
            Emit("    add");
            Emit("    stloc.1");
            Emit("    br loop_start");
            Emit("  loop_end:");
            Emit("    ldloc.0");
            Emit("    callvirt instance string [mscorlib]System.Text.StringBuilder::ToString()");
            Emit("    call void [mscorlib]System.Console::Write(string)");
            Emit("    ret");
            Emit("}");
            Emit("");

            // ReadInt
            Emit(".method public static int32 ReadInt() cil managed");
            Emit("{");
            Emit("    .maxstack 1");
            Emit("    call string [mscorlib]System.Console::ReadLine()");
            Emit("    call int32 [mscorlib]System.Int32::Parse(string)");
            Emit("    ret");
            Emit("}");
            Emit("");

            // ReadFloat
            Emit(".method public static float32 ReadFloat() cil managed");
            Emit("{");
            Emit("    .maxstack 1");
            Emit("    call string [mscorlib]System.Console::ReadLine()");
            Emit("    call float32 [mscorlib]System.Single::Parse(string)");
            Emit("    ret");
            Emit("}");
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                // === 标签 ===
                case OpCode.LABEL:
                    {
                        string name = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"  {name}:");
                    }
                    break;

                // === 数据传输 ===
                                                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;

                // === 栈操作 ===
                case OpCode.PUSH:
                    {
                        // .NET用计算栈，push = 把值压入计算栈
                        var src = instr.Operands[0];
                        LoadOperandToStack(src);
                        // 同时更新SP
                        Emit("    ldloc SP");
                        Emit("    ldc.i4.4");
                        Emit("    sub");
                        Emit("    dup");
                        Emit("    stloc SP");
                        // 存入memory[SP]
                        Emit("    ldsfld int32[] VMLProgram::Memory");
                        // 栈现在: value, newSP, Memory, newSP → 需要重排
                        // 简化：用临时变量
                        Emit("    ldloc SP");
                        LoadOperandToStack(src);
                        Emit("    stelem.i4");
                    }
                    break;
                case OpCode.POP:
                    {
                        var dst = instr.Operands[0];
                        // 从memory[SP]读取
                        Emit("    ldsfld int32[] VMLProgram::Memory");
                        Emit("    ldloc SP");
                        Emit("    ldelem.i4");
                        StoreStackToLocal(dst);
                        // SP += 4
                        Emit("    ldloc SP");
                        Emit("    ldc.i4.4");
                        Emit("    add");
                        Emit("    stloc SP");
                    }
                    break;

                // === 算术运算 ===
                case OpCode.ADD:
                    TranslateBinaryOp(instr, "add");
                    break;
                case OpCode.SUB:
                    TranslateBinaryOp(instr, "sub");
                    break;
                case OpCode.MUL:
                    TranslateBinaryOp(instr, "mul");
                    break;
                case OpCode.DIV:
                    TranslateBinaryOp(instr, "div");
                    break;
                case OpCode.MOD:
                    TranslateBinaryOp(instr, "rem");
                    break;
                case OpCode.INC:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(dst);
                        Emit("    ldc.i4.1");
                        Emit("    add");
                        StoreStackToLocal(dst);
                    }
                    break;
                case OpCode.DEC:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(dst);
                        Emit("    ldc.i4.1");
                        Emit("    sub");
                        StoreStackToLocal(dst);
                    }
                    break;
                case OpCode.NEG:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(dst);
                        Emit("    neg");
                        StoreStackToLocal(dst);
                    }
                    break;

                // === 逻辑运算 ===
                case OpCode.AND:
                    TranslateBinaryOp(instr, "and");
                    break;
                case OpCode.OR:
                    TranslateBinaryOp(instr, "or");
                    break;
                case OpCode.XOR:
                    TranslateBinaryOp(instr, "xor");
                    break;
                case OpCode.NOT:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(dst);
                        Emit("    ldc.i4.m1");
                        Emit("    xor");
                        StoreStackToLocal(dst);
                    }
                    break;
                case OpCode.SHL:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(instr.Operands[1]);
                        LoadOperandToStack(instr.Operands[2]);
                        Emit("    shl");
                        StoreStackToLocal(dst);
                    }
                    break;
                case OpCode.SHR:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(instr.Operands[1]);
                        LoadOperandToStack(instr.Operands[2]);
                        Emit("    shr");
                        StoreStackToLocal(dst);
                    }
                    break;

                // === 比较与跳转 ===
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.TEST:
                    {
                        LoadOperandToStack(instr.Operands[0]);
                        LoadOperandToStack(instr.Operands[1]);
                        Emit("    and");
                        // 结果存到CmpResult
                        Emit($"    stloc {CMP_RESULT_SLOT}");
                    }
                    break;
                case OpCode.JMP:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    br {label}");
                    }
                    break;
                case OpCode.JZ:
                case OpCode.JE:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    ldloc {CMP_RESULT_SLOT}");
                        Emit($"    brfalse {label}");
                    }
                    break;
                case OpCode.JNZ:
                case OpCode.JNE:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    ldloc {CMP_RESULT_SLOT}");
                        Emit($"    brtrue {label}");
                    }
                    break;
                case OpCode.JL:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    ldloc {CMP_RESULT_SLOT}");
                        Emit($"    blt {label}");
                    }
                    break;
                case OpCode.JLE:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    ldloc {CMP_RESULT_SLOT}");
                        Emit($"    ble {label}");
                    }
                    break;
                case OpCode.JG:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    ldloc {CMP_RESULT_SLOT}");
                        Emit($"    bgt {label}");
                    }
                    break;
                case OpCode.JGE:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    ldloc {CMP_RESULT_SLOT}");
                        Emit($"    bge {label}");
                    }
                    break;

                // === 函数调用 ===
                case OpCode.CALL:
                    {
                        string target = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        // .NET中VML函数在同一个方法内用标签跳转
                        // 保存返回地址到局部变量
                        string returnLabel = $"ret_{labelCounter++}";
                        Emit($"    ldstr \"{returnLabel}\"");
                        Emit("    stloc.s R15");
                        Emit($"    br {target}");
                        Emit($"  {returnLabel}:");
                    }
                    break;
                case OpCode.RET:
                    // 简化：从方法返回
                    Emit("    ret");
                    break;
                // case OpCode.RET_VAL:
                //     {
                //         var src = instr.Operands[0];
                //         LoadOperandToStack(src);
                //         Emit("    stloc.0");  // 返回值存R0
                //     }
                //     break;

                // === 系统调用 ===
                case OpCode.SYSCALL:
                    TranslateSyscall(instr);
                    break;
                case OpCode.HALT:
                    Emit("    ret");
                    break;
                case OpCode.NOP:
                    Emit("    nop");
                    break;

                // === 浮点运算 ===
                case OpCode.FADD:
                    TranslateFloatBinaryOp(instr, "add");
                    break;
                case OpCode.FSUB:
                    TranslateFloatBinaryOp(instr, "sub");
                    break;
                case OpCode.FMUL:
                    TranslateFloatBinaryOp(instr, "mul");
                    break;
                case OpCode.FDIV:
                    TranslateFloatBinaryOp(instr, "div");
                    break;
                case OpCode.FNEG:
                    {
                        var dst = instr.Operands[0];
                        LoadFloatToStack(dst);
                        Emit("    neg");
                        StoreStackToFloatLocal(dst);
                    }
                    break;
                case OpCode.FCMP:
                    {
                        LoadFloatToStack(instr.Operands[0]);
                        LoadFloatToStack(instr.Operands[1]);
                        // .NET浮点比较：用 ceq/clt/cgt 组合
                        // 简化：比较结果 -1/0/1 存到 CmpResult
                        Emit("    clt");           // a < b ?
                        Emit("    ldc.i4.0");
                        Emit("    ceq");           // !(a < b) → 0 or 1
                        // 这太简化了，用更完整的方案
                        // 先用减法近似
                        // 实际应该生成3路比较
                        Emit($"    stloc {CMP_RESULT_SLOT}");
                    }
                    break;

                // === 浮点转换 ===
                case OpCode.I2F:
                    {
                        LoadOperandToStack(instr.Operands[1]);
                        Emit("    conv.r4");
                        StoreStackToFloatLocal(instr.Operands[0]);
                    }
                    break;
                case OpCode.F2I:
                    {
                        LoadFloatToStack(instr.Operands[1]);
                        Emit("    conv.i4");
                        StoreStackToLocal(instr.Operands[0]);
                    }
                    break;
                case OpCode.F2D:
                    {
                        LoadFloatToStack(instr.Operands[1]);
                        Emit("    conv.r8");
                        // 存为float64（简化：存到float32局部变量，精度截断）
                        StoreStackToFloatLocal(instr.Operands[0]);
                    }
                    break;
                case OpCode.D2F:
                    {
                        LoadFloatToStack(instr.Operands[1]);
                        Emit("    conv.r4");
                        StoreStackToFloatLocal(instr.Operands[0]);
                    }
                    break;
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    LoadFloatToStack(instr.Operands[0]);
                    break;
                case OpCode.FPOP:
                    StoreStackToFloatLocal(instr.Operands[0]);
                    break;

                // === 栈帧管理 ===
                case OpCode.ENTER:
                    Emit("    // ENTER: .NET CLR自动管理栈帧");
                    break;
                case OpCode.LEAVE:
                    Emit("    // LEAVE: .NET CLR自动管理栈帧");
                    break;

                // === 地址计算 ===
                                // === 标志位 ===
                case OpCode.CLC:
                case OpCode.STC:
                    Emit($"    // {instr.Opcode}: 标志位操作在.NET中不适用");
                    break;

                                                                                case OpCode.MOVEB:
                    Emit("    conv.i1");
                    break;
                case OpCode.MOVEH:
                    Emit("    conv.i2");
                    break;
                case OpCode.PUSHB:
                case OpCode.PUSHH:
                    Emit("    // PUSHB/PUSHW - value already on stack");
                    break;
                case OpCode.POPB:
                    Emit("    conv.i1");
                    break;
                case OpCode.POPH:
                    Emit("    conv.i2");
                    break;
                case OpCode.INT:
                case OpCode.IRET:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.I2D:
                    Emit("    conv.r8");
                    break;
                case OpCode.D2I:
                    Emit("    conv.i4");
                    break;
                case OpCode.THROW:
                    Emit("    throw");
                    break;
                case OpCode.CATCH:
                    Emit("    // CATCH - exception handler start");
                    break;
                case OpCode.ENDCATCH:
                    Emit("    // ENDCATCH - exception handler end");
                    break;
                case OpCode.SHLV:
                    Emit("    shl");
                    break;
                case OpCode.SHRV:
                    Emit("    shr");
                    break;
                case OpCode.ZERO:
                    Emit("    ldc.i4.0");
                    break;

                // === 调试 ===
                case OpCode.BREAK:
                    Emit("    break");
                    break;

                // === 内联汇编 ===
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 符号扩展 (.NET 原生) / 条件移动+循环移位 (软件库) (v1.66.28+)
                case OpCode.SEXTB: Emit("    conv.i1"); break;
                case OpCode.SEXTH: Emit("    conv.i2"); break;
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"    call void VMLRuntime::__{instr.Opcode.ToString().ToLower()}()");
                    break;

                default:
                    Emit($"    // UNIMPLEMENTED: {instr.Opcode} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        // === 辅助方法 ===

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.IMMEDIATE)
            {
                LoadImmediate(Convert.ToInt32(src.Value));
                StoreStackToLocal(dst);
            }
            else if (src.Type == OperandType.REGISTER)
            {
                int srcSlot = GetLocalSlot(src);
                int dstSlot = GetLocalSlot(dst);
                if (srcSlot != dstSlot)
                {
                    Emit($"    ldloc {srcSlot}");
                    Emit($"    stloc {dstSlot}");
                }
            }
            else if (src.Type == OperandType.MEMORY)
            {
                string addr = ResolveAddress(src);
                Emit("    ldsfld int32[] VMLProgram::Memory");
                Emit($"    ldc.i4 {addr}");
                Emit("    ldelem.i4");
                StoreStackToLocal(dst);
            }
            else if (src.Type == OperandType.LABEL)
            {
                string labelName = src.Value?.ToString() ?? "";
                if (LabelMap.ContainsKey(labelName))
                {
                    Emit($"    ldc.i4 {LabelMap[labelName]}");
                }
                else
                {
                    Emit("    ldc.i4.0");
                }
                StoreStackToLocal(dst);
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string addr = ResolveAddress(dst);
            Emit("    ldsfld int32[] VMLProgram::Memory");
            Emit($"    ldc.i4 {addr}");
            LoadOperandToStack(src);
            Emit("    stelem.i4");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateBinaryOp(Instruction instr, string cilOp)
        {
            var dst = instr.Operands[0];
            LoadOperandToStack(instr.Operands[1]);
            LoadOperandToStack(instr.Operands[2]);
            Emit($"    {cilOp}");
            StoreStackToLocal(dst);
        }

        private void TranslateFloatBinaryOp(Instruction instr, string cilOp)
        {
            var dst = instr.Operands[0];
            LoadFloatToStack(instr.Operands[1]);
            LoadFloatToStack(instr.Operands[2]);
            Emit($"    {cilOp}");
            StoreStackToFloatLocal(dst);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];
            LoadOperandToStack(src1);
            LoadOperandToStack(src2);
            // sub → CmpResult: <0/0/>0
            Emit("    sub");
            Emit($"    stloc {CMP_RESULT_SLOT}");
        }

        private void TranslateSyscall(Instruction instr)
        {
            if (instr.Operands.Count > 0 && instr.Operands[0].Type == OperandType.IMMEDIATE)
            {
                int syscallNum = Convert.ToInt32(instr.Operands[0].Value);
                switch (syscallNum)
                {
                    case 1: // print integer
                        Emit("    ldloc.0");  // R0
                        Emit("    call void VMLProgram::VmlPrint(int32)");
                        break;
                    case 2: // print string
                        Emit("    ldloc.0");
                        Emit("    call void VMLProgram::VmlPrintString(int32)");
                        break;
                    case 4: // print newline
                        Emit("    call void [mscorlib]System.Console::WriteLine()");
                        break;
                    case 5: // read integer
                        Emit("    call int32 VMLProgram::ReadInt()");
                        Emit("    stloc.0");
                        break;
                    case 6: // read float
                        Emit("    call float32 VMLProgram::ReadFloat()");
                        Emit("    stloc 20");  // F0
                        break;
                    default:
                        Emit($"    // SYSCALL #{syscallNum}: 未实现");
                        break;
                }
            }
        }

        // === 操作数加载/存储 ===

        private void LoadImmediate(int val)
        {
            if (val == 0) Emit("    ldc.i4.0");
            else if (val == 1) Emit("    ldc.i4.1");
            else if (val == 2) Emit("    ldc.i4.2");
            else if (val == 3) Emit("    ldc.i4.3");
            else if (val == 4) Emit("    ldc.i4.4");
            else if (val == 5) Emit("    ldc.i4.5");
            else if (val == 6) Emit("    ldc.i4.6");
            else if (val == 7) Emit("    ldc.i4.7");
            else if (val == 8) Emit("    ldc.i4.8");
            else if (val == -1) Emit("    ldc.i4.m1");
            else if (val >= -128 && val <= 127) Emit($"    ldc.i4.s {val}");
            else Emit($"    ldc.i4 {val}");
        }

        private void LoadOperandToStack(Operand operand)
        {
            switch (operand.Type)
            {
                case OperandType.IMMEDIATE:
                    LoadImmediate(Convert.ToInt32(operand.Value));
                    break;
                case OperandType.REGISTER:
                    int slot = GetLocalSlot(operand);
                    Emit($"    ldloc {slot}");
                    break;
                case OperandType.MEMORY:
                    string addr = ResolveAddress(operand);
                    Emit("    ldsfld int32[] VMLProgram::Memory");
                    Emit($"    ldc.i4 {addr}");
                    Emit("    ldelem.i4");
                    break;
                case OperandType.LABEL:
                    string labelName = operand.Value?.ToString() ?? "";
                    if (LabelMap.ContainsKey(labelName))
                        Emit($"    ldc.i4 {LabelMap[labelName]}");
                    else
                        Emit("    ldc.i4.0");
                    break;
            }
        }

        private void StoreStackToLocal(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                int slot = GetLocalSlot(operand);
                Emit($"    stloc {slot}");
            }
            else if (operand.Type == OperandType.MEMORY)
            {
                string addr = ResolveAddress(operand);
                // 先存临时变量
                Emit("    stloc 18");  // tmp0
                Emit("    ldsfld int32[] VMLProgram::Memory");
                Emit($"    ldc.i4 {addr}");
                Emit("    ldloc 18");
                Emit("    stelem.i4");
            }
        }

        private void LoadFloatToStack(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                int regNum = Convert.ToInt32(operand.Value);
                if (FLOAT_REGISTER_MAP.ContainsKey(regNum))
                {
                    Emit($"    ldloc {FLOAT_REGISTER_MAP[regNum]}");
                }
                else
                {
                    // 从整数寄存器读取，做位级转换
                    Emit($"    ldloc {GetLocalSlot(operand)}");
                    // int → float 通过 BitConverter
                    // CIL没有直接指令，需要调用helper
                    Emit("    call float32 [mscorlib]System.BitConverter::Int32BitsToSingle(int32)");
                }
            }
            else if (operand.Type == OperandType.IMMEDIATE)
            {
                Emit($"    ldc.r4 {operand.Value}");
            }
        }

        private void StoreStackToFloatLocal(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                int regNum = Convert.ToInt32(operand.Value);
                if (FLOAT_REGISTER_MAP.ContainsKey(regNum))
                {
                    Emit($"    stloc {FLOAT_REGISTER_MAP[regNum]}");
                }
                else
                {
                    // float → int 位级转换
                    Emit("    call int32 [mscorlib]System.BitConverter::SingleToInt32Bits(float32)");
                    Emit($"    stloc {GetLocalSlot(operand)}");
                }
            }
        }

        private int GetLocalSlot(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                int regNum = Convert.ToInt32(operand.Value);
                return REGISTER_MAP.TryGetValue(regNum, out int slot) ? slot : regNum;
            }
            return 0;
        }

        private string ResolveAddress(Operand operand)
        {
            if (operand.Type == OperandType.MEMORY)
            {
                return operand.Value?.ToString() ?? "0";
            }
            return "0";
        }

        // SanitizeLabel → uses TranslatorVM.SanitizeLabel

        protected override void EmitCall(Instruction instr)
            => Emit($"    call void VMLRuntime::__{instr.Opcode.ToString().ToLower()}()");

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out int slot) ? $"local_{slot}" : $"local_{regNum}";
        }
    }
}
